// ── Read raw AI text from every possible field location ──────────────────────
const j = $input.item.json;

const rawResponse =
  j?.message?.content                    // standard chat completion
  || j?.choices?.[0]?.message?.content   // raw OpenAI API format
  || j?.text                             // older n8n OpenAI node
  || j?.content                          // some n8n versions
  || j?.output                           // fallback
  || j?.response                         // fallback
  || "";

// ── Pull meeting metadata from Node 2 ────────────────────────────────────────
const meetingTitle       = $('Set - Clean and Prepare Form Fields').first().json.meetingTitle || "";
const meetingDate        = $('Set - Clean and Prepare Form Fields').first().json.meetingDate || "";
const organizerEmail     = $('Set - Clean and Prepare Form Fields').first().json.organizerEmail || "";
const attendeeEmails     = $('Set - Clean and Prepare Form Fields').first().json.attendeeEmails || "";
const submissionTimestamp = $('Set - Clean and Prepare Form Fields').first().json.submissionTimestamp || "";

// ── Clean the response ────────────────────────────────────────────────────────
let cleanJson = rawResponse.trim();

// Strip markdown code fences (```json ... ``` or ``` ... ```)
cleanJson = cleanJson
  .replace(/^```(?:json)?\s*/i, "")
  .replace(/\s*```$/,           "")
  .trim();

// Replace literal \n escape sequences with real newlines
// This fixes the {\n"summary":... pattern you are seeing
cleanJson = cleanJson.replace(/\\n/g, "\n");

// ── Parse ─────────────────────────────────────────────────────────────────────
let parsed     = null;
let parseError = null;

try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parseError = e.message;
}

// ── Validate fields ───────────────────────────────────────────────────────────
if (parsed) {
  if (!parsed.summary)                        parsed.summary       = "Summary not available.";
  if (!Array.isArray(parsed.decisions))       parsed.decisions     = [];
  if (!Array.isArray(parsed.actionItems))     parsed.actionItems   = [];
  if (!Array.isArray(parsed.attendeeNames))   parsed.attendeeNames = [];
}

// ── Return ────────────────────────────────────────────────────────────────────
return {
  parseSuccess:       parsed !== null,
  parseError:         parseError || null,
  rawAiResponse:      rawResponse,
  cleanJsonAttempted: cleanJson,
  summary:            parsed?.summary       || null,
  decisions:          parsed?.decisions     || [],
  actionItems:        parsed?.actionItems   || [],
  attendeeNames:      parsed?.attendeeNames || [],
  meetingTitle,
  meetingDate,
  organizerEmail,
  attendeeEmails,
  submissionTimestamp
};

// Get the parsed AI data from Node 4
const data = $('Code - parse and Validate AI JSON Response').first().json;

const actionItems = data.actionItems || [];
const meetingTitle = data.meetingTitle || "";
const meetingDate = data.meetingDate || "";
const organizerEmail = data.organizerEmail || "";
const attendeeEmails = data.attendeeEmails || "";
const summary = data.summary || "";
const decisions = data.decisions || [];

// If no action items at all, return one placeholder
// so the workflow continues to the archive + email steps
if (actionItems.length === 0) {
  return [{
    json: {
      noActionItems: true,
      meetingTitle,
      meetingDate,
      organizerEmail,
      attendeeEmails,
      summary,
      decisions,
      totalActionItems: 0,
      description: null,
      assignee: null,
      dueDate: null,
      priority: null,
      isUnassigned: false
    }
  }];
}

// Return one item per action item
return actionItems.map((item, index) => {
  const assigneeRaw = (item.assignee || "").toString().trim();
  const isUnassigned = !assigneeRaw
    || assigneeRaw.toLowerCase() === "null"
    || assigneeRaw.toLowerCase() === "tbd"
    || assigneeRaw.toLowerCase() === "unassigned"
    || assigneeRaw.toLowerCase() === "n/a";

  return {
    json: {
      noActionItems: false,
      meetingTitle,
      meetingDate,
      organizerEmail,
      attendeeEmails,
      summary,
      decisions,
      totalActionItems: actionItems.length,
      description: item.description || "No description provided",
      assignee: isUnassigned ? null : assigneeRaw,
      dueDate: item.dueDate || null,
      priority: item.priority || "Medium",
      isUnassigned,
      actionItemIndex: index
    }
  };
});

const allItems = $input.all();

// Count items flagged as orphans
const unassignedItems = allItems.filter(item => item.json.flaggedAsOrphan === true);
const unassignedCount = unassignedItems.length;

// Build a list of unassigned task descriptions for the alert email
const unassignedList = unassignedItems.map(item => ({
  description: item.json.description || "No description",
  priority: item.json.priority || "Medium",
  dueDate: item.json.dueDate || "Not specified"
}));

// Carry forward meeting metadata from first item
const first = allItems[0]?.json || {};

return [{
  json: {
    unassignedCount,
    unassignedList,
    hasUnassigned: unassignedCount > 0,
    meetingTitle: first.meetingTitle,
    meetingDate: first.meetingDate,
    organizerEmail: first.organizerEmail,
    attendeeEmails: first.attendeeEmails,
    summary: first.summary,
    decisions: first.decisions,
    totalActionItems: first.totalActionItems
  }
}];

const allItems = $input.all();
const today = new Date();
const sevenDaysFromNow = new Date();
sevenDaysFromNow.setDate(today.getDate() + 7);

const atRiskTasks = allItems
  .map(item => item.json)
  .filter(row => {
    if ((row["Status"] || "").toLowerCase() !== "open") return false;
    const dueDateStr = row["Due Date"] || "";
    if (!dueDateStr) return false;
    const dueDate = new Date(dueDateStr);
    if (isNaN(dueDate.getTime())) return false;
    // Include overdue AND upcoming within 7 days
    return dueDate <= sevenDaysFromNow;
  })
  .sort((a, b) => Number(new Date(a["Due Date"])) - Number(new Date(b["Due Date"])));

return [{
  json: {
    atRiskTasks,
    taskCount: atRiskTasks.length,
    hasAtRiskTasks: atRiskTasks.length > 0,
    reportDate: today.toISOString().split('T')[0]
  }
}];

